package com.booksyde.service; import com.booksyde.dto.response.ContractResponse;import com.booksyde.entity.PublisherContractEntity;import com.booksyde.repository.PublisherContractRepository;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional; @Service public class ContractService{private final PublisherContractRepository repo;public ContractService(PublisherContractRepository r){repo=r;}@Transactional(readOnly=true)public List<ContractResponse> mine(UUID id){return repo.findAllByPublisherIdOrderByCreatedAtDesc(id).stream().map(this::map).toList();}@Transactional(readOnly=true)public List<ContractResponse> all(){return repo.findAllByOrderByCreatedAtDesc().stream().map(this::map).toList();}private ContractResponse map(PublisherContractEntity x){return new ContractResponse(x.getId(),x.getPublisherId(),x.getTitle(),x.getStatus(),x.getPublisherPercentage(),x.getBooksydePercentage(),x.getContractDate(),x.getStartsAt(),x.getEndsAt(),x.getFileName(),x.getNotes(),x.getCreatedAt());}}
